WITH flagged AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM web_events), sessions_web_events AS (SELECT id, session_id, page, event_time, duration_sec, SUM(new_group_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT burst_id, PERCENTILE_APPROX(burst_id, ARRAY(0.25, 0.5, 0.75)) AS burst_id_quartiles, SORT_ARRAY(COLLECT_SET(page)) AS page_list, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, ROUND(AVG(burst_id), 2) AS avg_burst_id, COUNT(CASE WHEN page = '/product' THEN 1 END) AS product_count, MAX(event_time) AS last_seen FROM sessions_web_events GROUP BY burst_id ORDER BY avg_duration_sec DESC NULLS LAST;
